import { useState } from "react";

export default function Tppp() {
    const [Id, SetId] = useState("");
    const [Des, SetDes] = useState("");
    const [Price, SetPrice] = useState("");
    const [Total, SetTotal] = useState(0);
    const [List, SetList] = useState([]); 
    const elmStyl={
        form:{
            display:"flex",
            flexDirection:"column",
            gap:"12px",
            margin:"30px",
            border:"2px solid #000",
            borderRadius:"12px",
            backgroundColor:"#fff"

            
        },
        input:{
            padding:"12px",
            fontSize:"15px",
            borderRadius:"10px",
            border:"1px solis #0c0c0cff",
        },
        button:{
            padding:"12px",
            borderRadius:"10px",
            background:"#6b8cff",
            color:"white",
            fontSize:"16px",
            fontWeight:"600",

        },
        label:{
            display:"flex",
            flexDirection:"column",
            gap:"6px",
            fontSize:"14px",
            color:"#444",
            fontWeight:"500",


        }

    };


 
      

    let f1 = (event) => { SetId(event.target.value); }
    let f2 = (event) => { SetDes(event.target.value); }
    let f3 = (event) => { SetPrice(event.target.value); }

    const AddToList = () => {
        if (Id && Des && Price) {
            
            SetList([...List, {
                id: Id,
                des: Des,
                price: Number(Price) 
            }]);
            
            SetId("");
            SetDes("");
            SetPrice("");
        }
    }

    const Calculate = () => {
        const sum = List.reduce((acc, item) => acc + item.price, 0);
        SetTotal(sum);
    }

    return (
        <div>
            <form style={elmStyl}>
                <label>ID</label>
                <input type="text" value={Id} onChange={f1} />
                
                <label>Designation</label>
                <input type="text" value={Des} onChange={f2} />
                
                <label>Prix</label>
                <input type="text" value={Price} onChange={f3} />
                
                <button type="button" onClick={AddToList}>Ajouter</button>

                <ul>
                    {List.map((item, index) => (
                        // Use item properties instead of index
                        <li key={index} >
                            <button type="button" ></button>
                            {item.id} | {item.des} | {item.price}
                        </li>
                    ))}
                </ul>

                <button type="button" onClick={Calculate}>
                    Calculer Total
                </button>
                
                <div>Total: {Total}</div>
            </form>
        </div>
    )
}
